eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   agents: () => (/* binding */ agents),\n/* harmony export */   getAgentBySlug: () => (/* binding */ getAgentBySlug),\n/* harmony export */   getAgentsByCategory: () => (/* binding */ getAgentsByCategory),\n/* harmony export */   getCategoryColor: () => (/* binding */ getCategoryColor)\n/* harmony export */ });\nconst agents = [\n    {\n        slug: \"ocr-agent\",\n        number: \"01\",\n        name: \"OCR\",\n        fullName: \"OCR Agent\",\n        port: 5001,\n        status: \"active\",\n        category: \"input\",\n        purpose: \"Converts handwritten or scanned clinical notes into machine-readable text using Azure GPT-4o-mini vision capabilities. The agent processes uploaded images of clinical documents and produces structured text output with per-line confidence scoring. It preserves the original layout and marks illegible sections with [ILLEGIBLE] tags rather than guessing, ensuring downstream agents receive honest input.\",\n        inputSchema: {\n            image: \"base64 | multipart file\",\n            department: \"string (optional)\",\n            patient_id: \"string\"\n        },\n        outputSchema: {\n            raw_text: \"string\",\n            confidence: \"number (0-1)\",\n            illegible_count: \"number\",\n            line_confidences: \"number[]\"\n        },\n        promptStrategy: \"Zero-shot OCR specialist prompt with strict no-correction rules. The model is instructed to transcribe exactly what it sees, never infer missing words, and tag uncertain regions as [ILLEGIBLE]. Confidence is computed deterministically by counting [ILLEGIBLE] tags relative to total line count.\",\n        pipelinePosition: \"First agent in the handwritten note workflow. Receives raw image input and produces plain text that feeds into the SOAP Extractor for structured parsing.\",\n        exampleInput: JSON.stringify({\n            image: \"<base64-encoded-png>\",\n            department: \"Cardiology\",\n            patient_id: \"10000935\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            raw_text: \"Patient complains of chest pain radiating to left arm...\",\n            confidence: 0.87,\n            illegible_count: 2\n        }, null, 2),\n        failureModes: [\n            \"Very low-resolution images may yield mostly [ILLEGIBLE] output with confidence below 0.3\",\n            \"Non-English handwriting is not supported and will produce garbled text\",\n            \"Photos with heavy shadows or skew may lose line structure\",\n            \"Rate-limited by Azure OpenAI token quotas on the vision endpoint\"\n        ],\n        sourceLocation: \"ocr-agent/app/ocr.py\"\n    },\n    {\n        slug: \"soap-extractor\",\n        number: \"02\",\n        name: \"SOAP\",\n        fullName: \"SOAP Extractor\",\n        port: 5002,\n        status: \"active\",\n        category: \"input\",\n        purpose: \"Parses raw clinical text into structured SOAP (Subjective, Objective, Assessment, Plan) JSON and then converts each section into standardized ClinicalFact objects. Uses a two-stage pipeline: first an LLM extraction pass with few-shot examples, then a deterministic conversion stage that maps SOAP fields to the ClinicalFact schema. This ensures consistent output format regardless of LLM variability.\",\n        inputSchema: {\n            raw_text: \"string\",\n            patient_id: \"string\",\n            department: \"string (optional)\"\n        },\n        outputSchema: {\n            soap: \"{ subjective: string, objective: string, assessment: string, plan: string }\",\n            clinical_facts: \"ClinicalFact[]\"\n        },\n        promptStrategy: \"Few-shot prompting with 3 curated examples covering common clinical note styles. Uses spiral prompting methodology where the model first identifies key clinical observations, then maps them to SOAP categories, and finally extracts discrete clinical facts with certainty scores.\",\n        pipelinePosition: \"Second agent in the handwritten note workflow. Receives OCR text and produces structured SOAP + ClinicalFacts that feed into the review step before ingestion into the Fact Graph.\",\n        exampleInput: JSON.stringify({\n            raw_text: \"Patient complains of chest pain radiating to left arm. BP 140/90. Assessment: Possible ACS. Plan: ECG stat, troponin levels.\",\n            patient_id: \"10000935\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            soap: {\n                subjective: \"Chest pain radiating to left arm\",\n                objective: \"BP 140/90\",\n                assessment: \"Possible acute coronary syndrome\",\n                plan: \"ECG stat, troponin levels\"\n            },\n            clinical_facts: [\n                {\n                    entity_name: \"chest_pain\",\n                    certainty: 0.95,\n                    body_region: \"chest\",\n                    temporal_change: \"NEW\"\n                }\n            ]\n        }, null, 2),\n        failureModes: [\n            \"Highly abbreviated or shorthand notes may be misclassified between SOAP sections\",\n            \"Notes without clear structure may produce empty Subjective/Objective fields\",\n            \"Very long notes (>2000 words) may hit token limits and truncate the Plan section\",\n            \"Non-standard medical abbreviations may be expanded incorrectly\"\n        ],\n        sourceLocation: \"soap-extractor/app/extractor.py\"\n    },\n    {\n        slug: \"radiology-extractor\",\n        number: \"03\",\n        name: \"RAD\",\n        fullName: \"Radiology Extractor\",\n        port: 5003,\n        status: \"active\",\n        category: \"input\",\n        purpose: \"Extracts RadLex-grounded findings from radiology reports using a hybrid rule-based and LLM approach. Tier 0 uses 159 hand-crafted regex patterns to identify common findings without any LLM call, providing instant and deterministic extraction. Tier 1 uses LLM extraction for complex or ambiguous findings. A 4-tier grounding pipeline (TF-IDF, Fuzzy, LLM, Manual) maps every finding to RadLex ontology terms. Supports paired report processing for temporal change detection.\",\n        inputSchema: {\n            report_text: \"string\",\n            patient_id: \"string\",\n            modality: \"string (CT | MRI | PET | X-Ray | Ultrasound)\",\n            body_region: \"string\",\n            report_date: \"string (ISO date)\"\n        },\n        outputSchema: {\n            clinical_facts: \"ClinicalFact[]\",\n            extraction_tier: \"number (0 | 1)\",\n            grounding_stats: \"{ tfidf: number, fuzzy: number, llm: number, ungrounded: number }\"\n        },\n        promptStrategy: \"Hybrid rule+LLM approach. 159 regex patterns handle common findings deterministically (Tier 0). For remaining findings, LLM extraction uses structured output prompting with RadLex vocabulary priming. The grounding pipeline tries TF-IDF similarity first, then fuzzy matching, then LLM-based mapping, falling back to ungrounded only as a last resort.\",\n        pipelinePosition: \"Primary agent in the radiology workflow. Receives raw report text and produces grounded ClinicalFacts that go through human review before ingestion into the Fact Graph.\",\n        exampleInput: JSON.stringify({\n            report_text: \"FINDINGS: There is a 2.3 cm nodule in the right upper lobe. Moderate left-sided pleural effusion. No pneumothorax.\",\n            patient_id: \"19540374\",\n            modality: \"CT\",\n            body_region: \"chest\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            clinical_facts: [\n                {\n                    entity_name: \"pulmonary_nodule\",\n                    radlex_id: \"RID3875\",\n                    certainty: 0.95,\n                    body_region: \"chest\",\n                    temporal_change: \"NEW\",\n                    negated: false,\n                    measurements: {\n                        size_cm: 2.3\n                    }\n                },\n                {\n                    entity_name: \"pleural_effusion\",\n                    radlex_id: \"RID4836\",\n                    certainty: 0.92,\n                    body_region: \"chest\",\n                    temporal_change: \"NEW\",\n                    negated: false\n                },\n                {\n                    entity_name: \"pneumothorax\",\n                    radlex_id: \"RID4799\",\n                    certainty: 0.98,\n                    body_region: \"chest\",\n                    temporal_change: \"ABSENT\",\n                    negated: true\n                }\n            ],\n            extraction_tier: 0,\n            grounding_stats: {\n                tfidf: 2,\n                fuzzy: 1,\n                llm: 0,\n                ungrounded: 0\n            }\n        }, null, 2),\n        failureModes: [\n            \"Regex patterns may miss rare or newly described findings not in the pattern library\",\n            \"Comparative reports without a prior study reference may miss temporal changes\",\n            \"Non-standard report formats (bullet points, tables) may confuse section parsing\",\n            \"RadLex grounding may map to parent terms when a more specific child term exists\"\n        ],\n        sourceLocation: \"radiology-extractor/app/extractor.py\"\n    },\n    {\n        slug: \"voice-transcription\",\n        number: \"04\",\n        name: \"VOI\",\n        fullName: \"Voice Transcription\",\n        port: 5004,\n        status: \"active\",\n        category: \"input\",\n        purpose: \"Converts audio recordings of clinical conversations to timestamped transcripts using Sarvam AI Saaras v3 speech-to-text model. Handles Hindi-English code-mixing common in Indian clinical settings. Provides speaker diarization to distinguish between clinician and patient voices. Outputs a structured transcript with timestamps that feeds into the Counselling Summarizer.\",\n        inputSchema: {\n            audio: \"multipart file (wav | mp3 | m4a)\",\n            patient_id: \"string\",\n            language_hint: \"string (optional, default: hi-en)\"\n        },\n        outputSchema: {\n            transcript: \"{ speaker: string, text: string, start_ms: number, end_ms: number }[]\",\n            duration_seconds: \"number\",\n            language_detected: \"string\"\n        },\n        promptStrategy: \"No LLM prompting involved. Uses Sarvam AI Saaras v3 ASR model directly for transcription. Speaker diarization is performed as a post-processing step using energy-based segmentation. Language detection is automatic via the multilingual model.\",\n        pipelinePosition: \"First agent in the counselling workflow. Receives raw audio and produces timestamped transcript that feeds into the Counselling Summarizer for clinical fact extraction.\",\n        exampleInput: JSON.stringify({\n            audio: \"<audio-file.wav>\",\n            patient_id: \"10000935\",\n            language_hint: \"hi-en\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            transcript: [\n                {\n                    speaker: \"Doctor\",\n                    text: \"Aapko kab se pain ho raha hai?\",\n                    start_ms: 0,\n                    end_ms: 2500\n                },\n                {\n                    speaker: \"Patient\",\n                    text: \"Last week se, doctor. Left side mein.\",\n                    start_ms: 2600,\n                    end_ms: 5100\n                }\n            ],\n            duration_seconds: 45.2,\n            language_detected: \"hi-en\"\n        }, null, 2),\n        failureModes: [\n            \"Background noise in clinical settings may reduce transcription accuracy significantly\",\n            \"Audio files longer than 10 minutes may timeout due to processing constraints\",\n            \"Heavy dialect or accent variations may not be well-handled by the ASR model\",\n            \"Speaker diarization may fail with more than 3 speakers in the conversation\"\n        ],\n        sourceLocation: \"2nd/app/main.py\"\n    },\n    {\n        slug: \"counselling-summarizer\",\n        number: \"05\",\n        name: \"COUN\",\n        fullName: \"Counselling Summarizer\",\n        port: 5005,\n        status: \"active\",\n        category: \"input\",\n        purpose: \"Extracts clinical facts from counselling session transcripts, categorizing them into CONCERN, ACTION, DECISION, EMOTIONAL, and FOLLOW_UP types. Includes guardrails for sensitive mental health content to ensure appropriate handling. Produces structured clinical facts that undergo human review before ingestion into the patient record.\",\n        inputSchema: {\n            transcript: \"TranscriptSegment[]\",\n            patient_id: \"string\",\n            session_type: \"string (optional)\"\n        },\n        outputSchema: {\n            clinical_facts: \"ClinicalFact[]\",\n            session_summary: \"string\",\n            categories: \"{ CONCERN: number, ACTION: number, DECISION: number, EMOTIONAL: number, FOLLOW_UP: number }\"\n        },\n        promptStrategy: \"Structured extraction prompt with explicit category definitions and examples for each fact type. Includes guardrails that flag potentially sensitive content (suicidal ideation, abuse disclosure) for immediate clinician attention rather than standard review. Uses chain-of-thought reasoning to distinguish between patient-reported concerns and clinician observations.\",\n        pipelinePosition: \"Second agent in the counselling workflow. Receives transcript from Voice Transcription and produces categorized ClinicalFacts that go through human review before Fact Graph ingestion.\",\n        exampleInput: JSON.stringify({\n            transcript: [\n                {\n                    speaker: \"Doctor\",\n                    text: \"How have you been feeling since the last session?\"\n                },\n                {\n                    speaker: \"Patient\",\n                    text: \"The medication is helping with sleep but I still feel anxious.\"\n                }\n            ],\n            patient_id: \"10000935\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            clinical_facts: [\n                {\n                    entity_name: \"sleep_improvement\",\n                    category: \"ACTION\",\n                    certainty: 0.85,\n                    source_text: \"medication is helping with sleep\"\n                },\n                {\n                    entity_name: \"persistent_anxiety\",\n                    category: \"CONCERN\",\n                    certainty: 0.9,\n                    source_text: \"still feel anxious\"\n                }\n            ],\n            session_summary: \"Patient reports medication-assisted sleep improvement with persistent anxiety.\",\n            categories: {\n                CONCERN: 1,\n                ACTION: 1,\n                DECISION: 0,\n                EMOTIONAL: 0,\n                FOLLOW_UP: 0\n            }\n        }, null, 2),\n        failureModes: [\n            \"Transcription errors from the Voice agent may propagate and cause misidentified concerns\",\n            \"Sensitive content guardrails may be overly cautious, flagging benign statements\",\n            \"Sessions with heavy code-mixing may lose nuance in the English-language fact extraction\",\n            \"Very long sessions (>1 hour) may lose context in later portions of the transcript\"\n        ],\n        sourceLocation: \"3rd/counselling-summarizer/app/summarizer.py\"\n    },\n    {\n        slug: \"fact-graph-engine\",\n        number: \"06\",\n        name: \"FG\",\n        fullName: \"Fact Graph Engine\",\n        port: 5006,\n        status: \"active\",\n        category: \"core\",\n        purpose: \"The central append-only clinical fact store that maintains a longitudinal patient record. Uses no LLM — all operations are deterministic. Performs entity merge (deduplication of equivalent clinical findings), ontology grounding via RadLex hierarchy, and trajectory tracking to monitor how findings change over time. Backed by SQLite with the RadLex ontology loaded as a lookup hierarchy.\",\n        inputSchema: {\n            patient_id: \"string\",\n            clinical_facts: \"ClinicalFact[]\",\n            source_workflow: \"string\"\n        },\n        outputSchema: {\n            entities_created: \"number\",\n            entities_updated: \"number\",\n            entities_merged: \"number\",\n            patient_entity_count: \"number\"\n        },\n        promptStrategy: \"No LLM prompting. All operations are deterministic. Entity merge uses canonical name normalization, RadLex ID matching, and configurable similarity thresholds. Trajectory tracking compares incoming certainty scores and temporal markers against existing entity state to compute trends (improving, worsening, stable).\",\n        pipelinePosition: \"Central hub that all workflows feed into after human review. Receives approved ClinicalFacts and maintains the canonical patient state. Queried by the Summary Generator and QA Agent for downstream processing.\",\n        exampleInput: JSON.stringify({\n            patient_id: \"19540374\",\n            clinical_facts: [\n                {\n                    entity_name: \"pleural_effusion\",\n                    radlex_id: \"RID4836\",\n                    certainty: 0.92,\n                    body_region: \"chest\"\n                }\n            ],\n            source_workflow: \"radiology-report\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            entities_created: 0,\n            entities_updated: 1,\n            entities_merged: 0,\n            patient_entity_count: 155\n        }, null, 2),\n        failureModes: [\n            \"Entity merge may incorrectly merge distinct findings with similar names (e.g., left vs right pleural effusion)\",\n            \"RadLex hierarchy lookups may be slow if the ontology cache is not warmed\",\n            \"SQLite write contention under concurrent workflow submissions for the same patient\",\n            \"Trajectory tracking requires at least 2 observations to compute a trend\"\n        ],\n        sourceLocation: \"fact-graph-service/app/graph.py\"\n    },\n    {\n        slug: \"department-merger\",\n        number: \"07\",\n        name: \"DEPT\",\n        fullName: \"Department Merger\",\n        port: 5007,\n        status: \"active\",\n        category: \"processing\",\n        purpose: \"Merges clinical notes from multiple hospital departments into a unified set of clinical facts. Performs parallel extraction from each department note, then aligns entities across departments and detects conflicts (e.g., different certainty scores or contradictory findings for the same condition). Uses LLM-powered conflict analysis to suggest resolutions.\",\n        inputSchema: {\n            patient_id: \"string\",\n            department_notes: \"{ department: string, text: string, date: string, author?: string }[]\"\n        },\n        outputSchema: {\n            clinical_facts: \"ClinicalFact[]\",\n            conflicts: \"{ entity: string, departments: string[], description: string, resolution: string }[]\",\n            department_count: \"number\"\n        },\n        promptStrategy: \"Two-stage approach. First, each department note is independently parsed for clinical facts using department-aware prompting (e.g., cardiology notes emphasize cardiac findings). Second, an alignment pass identifies duplicate entities across departments and a conflict analysis prompt evaluates contradictory findings, suggesting resolutions based on clinical hierarchy (specialist opinion weighted higher).\",\n        pipelinePosition: \"Primary agent in the department merge workflow. Receives multiple department notes and produces a unified ClinicalFact set with conflict annotations that go through human review before Fact Graph ingestion.\",\n        exampleInput: JSON.stringify({\n            patient_id: \"10000935\",\n            department_notes: [\n                {\n                    department: \"Cardiology\",\n                    text: \"Echo shows EF 35%. Moderate MR.\",\n                    date: \"2182-07-01\",\n                    author: \"Dr. Smith\"\n                },\n                {\n                    department: \"Internal Medicine\",\n                    text: \"Cardiac function appears preserved. Mild MR on echo.\",\n                    date: \"2182-07-02\",\n                    author: \"Dr. Jones\"\n                }\n            ]\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            clinical_facts: [\n                {\n                    entity_name: \"reduced_ejection_fraction\",\n                    certainty: 0.9,\n                    body_region: \"chest\",\n                    source_department: \"Cardiology\"\n                },\n                {\n                    entity_name: \"mitral_regurgitation\",\n                    certainty: 0.85,\n                    body_region: \"chest\"\n                }\n            ],\n            conflicts: [\n                {\n                    entity: \"mitral_regurgitation\",\n                    departments: [\n                        \"Cardiology\",\n                        \"Internal Medicine\"\n                    ],\n                    description: \"Severity disagreement: Moderate (Cardiology) vs Mild (Internal Medicine)\",\n                    resolution: \"Cardiology specialist assessment preferred: Moderate MR\"\n                }\n            ],\n            department_count: 2\n        }, null, 2),\n        failureModes: [\n            \"Department notes from different time periods may reflect legitimate clinical change, not true conflict\",\n            \"Notes with very different terminology styles may miss entity alignment\",\n            \"Conflict resolution may incorrectly prefer one department over another\",\n            \"More than 5 departments may hit token limits in the conflict analysis pass\"\n        ],\n        sourceLocation: \"4th/department-merger/app/merger.py\"\n    },\n    {\n        slug: \"summary-generator\",\n        number: \"08\",\n        name: \"SUMM\",\n        fullName: \"Summary Generator\",\n        port: 5008,\n        status: \"active\",\n        category: \"processing\",\n        purpose: \"Generates NABH (National Accreditation Board for Hospitals) compliant discharge summaries from the patient fact graph data. Uses a template-based approach with LLM composition to produce structured, standardized discharge documents. Pulls all approved entities from the Fact Graph and organizes them into clinically appropriate sections.\",\n        inputSchema: {\n            patient_id: \"string\",\n            admission_date: \"string (ISO date)\",\n            discharge_date: \"string (ISO date)\",\n            attending_physician: \"string\",\n            department: \"string\",\n            template: \"string (default: nabh_standard)\",\n            include_recist: \"boolean\"\n        },\n        outputSchema: {\n            summary_text: \"string (markdown)\",\n            sections: \"string[]\",\n            entity_count: \"number\",\n            template_used: \"string\"\n        },\n        promptStrategy: \"Template-based composition where each discharge summary section (Chief Complaint, History of Present Illness, Hospital Course, Discharge Instructions, etc.) is generated by a focused prompt that receives only the relevant entities for that section. The final summary is assembled deterministically from section outputs. RECIST criteria integration is optional and pulls measurement trajectory data.\",\n        pipelinePosition: \"First agent in the discharge summary pipeline. Pulls data from the Fact Graph and produces a draft summary that feeds into the QA Agent for validation before final output through the Translation Layer.\",\n        exampleInput: JSON.stringify({\n            patient_id: \"19540374\",\n            admission_date: \"2182-06-01\",\n            discharge_date: \"2182-07-15\",\n            attending_physician: \"Dr. Sharma\",\n            department: \"Oncology\",\n            template: \"nabh_standard\",\n            include_recist: true\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            summary_text: \"# Discharge Summary\\n\\n## Patient Information\\n...\\n\\n## Hospital Course\\n...\",\n            sections: [\n                \"Patient Information\",\n                \"Chief Complaint\",\n                \"History of Present Illness\",\n                \"Hospital Course\",\n                \"Discharge Medications\",\n                \"Follow-up Instructions\"\n            ],\n            entity_count: 42,\n            template_used: \"nabh_standard\"\n        }, null, 2),\n        failureModes: [\n            \"Patients with very few entities may produce sparse summaries with placeholder text\",\n            \"RECIST criteria require measurement data that may not be available for all entities\",\n            \"Very long hospital stays with hundreds of entities may exceed summary length limits\",\n            \"Template sections may not cover all speciality-specific documentation requirements\"\n        ],\n        sourceLocation: \"5th/app/generator.py\"\n    },\n    {\n        slug: \"qa-agent\",\n        number: \"09\",\n        name: \"QA\",\n        fullName: \"QA Agent\",\n        port: 5009,\n        status: \"active\",\n        category: \"output\",\n        purpose: \"Validates discharge summaries against source facts in the Fact Graph to ensure accuracy and completeness. Performs traceability checking — every claim in the summary must be traceable to an approved clinical entity. Issues a PASS or FAIL verdict with a detailed list of issues including missing entities, unsupported claims, and inconsistencies.\",\n        inputSchema: {\n            summary_text: \"string\",\n            patient_id: \"string\",\n            source_entities: \"ClinicalEntity[]\"\n        },\n        outputSchema: {\n            verdict: \"PASS | FAIL\",\n            score: \"number (0-100)\",\n            issues: \"{ type: string, severity: string, description: string, location: string }[]\",\n            traceable_claims: \"number\",\n            total_claims: \"number\"\n        },\n        promptStrategy: \"Two-pass validation. First pass: claim extraction — identify every factual claim in the summary text. Second pass: traceability checking — for each claim, search the source entities for a matching fact. Claims without a traceable source are flagged. Severity is assigned based on clinical impact (medication errors are critical, formatting issues are low).\",\n        pipelinePosition: \"Second agent in the discharge summary pipeline. Receives the generated summary and source entities, validates correctness, and passes the verdict to the orchestrator. A FAIL verdict blocks translation and output generation until issues are resolved.\",\n        exampleInput: JSON.stringify({\n            summary_text: \"Patient had bilateral pleural effusion requiring thoracentesis...\",\n            patient_id: \"19540374\",\n            source_entities: [\n                {\n                    entity_name: \"pleural_effusion\",\n                    certainty: 0.92,\n                    body_region: \"chest\"\n                }\n            ]\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            verdict: \"FAIL\",\n            score: 78,\n            issues: [\n                {\n                    type: \"unsupported_claim\",\n                    severity: \"high\",\n                    description: 'Summary states \"bilateral\" but source only documents unilateral effusion',\n                    location: \"Hospital Course, paragraph 2\"\n                },\n                {\n                    type: \"missing_procedure\",\n                    severity: \"medium\",\n                    description: \"Thoracentesis mentioned but not found in source entities\",\n                    location: \"Hospital Course, paragraph 2\"\n                }\n            ],\n            traceable_claims: 14,\n            total_claims: 18\n        }, null, 2),\n        failureModes: [\n            \"Paraphrased claims may not match source entities despite being semantically equivalent\",\n            \"Negated findings in the summary may be incorrectly flagged as unsupported\",\n            \"Very long summaries with many claims may hit token limits during validation\",\n            \"Claims about procedures or medications may not have corresponding Fact Graph entities\"\n        ],\n        sourceLocation: \"6th/qa-agent/app/validator.py\"\n    },\n    {\n        slug: \"translation-layer\",\n        number: \"10\",\n        name: \"TRANS\",\n        fullName: \"Translation Layer\",\n        port: 5010,\n        status: \"active\",\n        category: \"output\",\n        purpose: \"Translates validated discharge summaries into Indian regional languages using the Sarvam AI translation API. Supports Hindi, Marathi, Tamil, Telugu, and other major Indian languages. Also provides text-to-speech audio generation for accessibility, PDF document generation for printing, and FHIR R4 JSON export for interoperability with hospital information systems.\",\n        inputSchema: {\n            summary_text: \"string\",\n            target_language: \"string (hi | mr | ta | te | en)\",\n            generate_audio: \"boolean\",\n            generate_pdf: \"boolean\",\n            generate_fhir: \"boolean\",\n            patient_id: \"string\"\n        },\n        outputSchema: {\n            translated_text: \"string\",\n            audio_url: \"string | null\",\n            pdf_url: \"string | null\",\n            fhir_json: \"object | null\",\n            target_language: \"string\"\n        },\n        promptStrategy: \"No LLM prompting for translation — uses Sarvam AI translation API directly. Medical terminology is preserved untranslated when no equivalent exists in the target language. PDF generation uses a template with hospital branding placeholders. FHIR export maps summary sections to DiagnosticReport and Composition resources.\",\n        pipelinePosition: \"Final agent in the discharge summary pipeline. Receives QA-validated summary and produces translated text, audio, PDF, and FHIR outputs. This is the terminal step — outputs go directly to the clinician or hospital system.\",\n        exampleInput: JSON.stringify({\n            summary_text: \"# Discharge Summary\\n\\nPatient was admitted for...\",\n            target_language: \"hi\",\n            generate_audio: true,\n            generate_pdf: true,\n            generate_fhir: false,\n            patient_id: \"19540374\"\n        }, null, 2),\n        exampleOutput: JSON.stringify({\n            translated_text: \"#退院サマリー (translated to Hindi in practice)\",\n            audio_url: \"/outputs/19540374_summary_hi.wav\",\n            pdf_url: \"/outputs/19540374_summary_hi.pdf\",\n            fhir_json: null,\n            target_language: \"hi\"\n        }, null, 2),\n        failureModes: [\n            \"Sarvam API rate limits may cause timeouts for very long summaries\",\n            \"Medical jargon may be mistranslated in languages with limited medical vocabulary\",\n            \"Audio generation for very long summaries (>5000 words) may be truncated\",\n            \"FHIR export may not capture all custom fields from the clinical workflow\"\n        ],\n        sourceLocation: \"7th/app/translator.py\"\n    }\n];\nfunction getAgentBySlug(slug) {\n    return agents.find((a)=>a.slug === slug);\n}\nfunction getAgentsByCategory(category) {\n    return agents.filter((a)=>a.category === category);\n}\nfunction getCategoryColor(category) {\n    switch(category){\n        case \"input\":\n            return \"teal\";\n        case \"core\":\n            return \"amber\";\n        case \"processing\":\n            return \"blue\";\n        case \"output\":\n            return \"purple\";\n    }\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/agents-data.ts\n");

